fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a.len() == b.len()`. We iterate over both vectors in lockstep,
    // compare each pair of elements, and collect the boolean results.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x >= y)
     .collect()
}

